WITH with_last AS (SELECT s.*, latest.stock_qty, latest.brand FROM suppliers s LEFT JOIN LATERAL (SELECT c.stock_qty, c.brand FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT brand, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN brand = 'Initech' THEN 1 END), 0), 2) AS stock_qty_per_initech, STDDEV_SAMP(rating) AS rating_stddev, COUNT_IF(brand = 'Acme') AS acme_events FROM with_last GROUP BY brand ORDER BY rating_stddev DESC NULLS FIRST
